.page-num { font-weight: 700; color: var(--text-main); padding: 0.3rem 0.7rem; background: var(--neo-bg); border-radius: 10px; font-size: 0.75rem; box-shadow: var(--neo-shadow-inset); }

/* Modal Overlays */
