`;

export default function App() {
  const [session, setSession] = useState(() => apiService.getCurrentSession());
  const [authView, setAuthView] = useState('login');

  return (
    <>
      <style>{inlineStyles}</style>

      <div className="orb orb-1"></div>
      <div className="orb orb-2"></div>

      {!session ? (
        authView === 'login' ? (
          <Login setSession={setSession} setAuthView={setAuthView} />
        ) : (
          <Register setSession={setSession} setAuthView={setAuthView} />
        )
      ) : (
        <Dashboard session={session} setSession={setSession} />
      )}
    </>
  );
}
